    "home_faq_a2": "হ্যাঁ! আমাদের জেমিনি ভিশন ওসিআর ল্যাব পিডিএফ ফাইল পার্স করে এবং দ্রুত বিশ্লেষণের জন্য মানসমূহ স্বয়ংক্রিয়ভাবে পূরণ করে।",
    "home_faq_q3": "নিউট্রিয়াই কি নিরামিষ ও ভেগান ডায়েট সমর্থন করে?",
    "home_faq_a3": "অবশ্যই! আমাদের খাবার সুপারিশকারী সম্পূর্ণ প্রোটিন, আয়রন এবং বি১২ এর পর্যাপ্ততা নিশ্চিত করে।",
    "home_faq_q4": "PWA অ্যাপ কিভাবে অ্যাপ স্টোর ছাড়া কাজ করে?",
    "home_faq_a4": "নিউট্রিয়াই প্রোগ্রেসিভ ওয়েব অ্যাপ প্রযুক্তিতে তৈরি। ক্রোম বা সাফারি খুলে 'ইনস্টল' এ ট্যাপ করুন।",
    "home_pwa_banner_title": "যেকোনো ডিভাইসে নিউট্রিয়াই অ্যাপ ইনস্টল করুন",
