    "home_faq_a1": "न्यूट्री-एआई एनएचएएनईएस क्लिनिकल डेटासेट पर 94.8% F1-स्कोर सटीकता प्राप्त करता है। हमारा रैंडम फॉरेस्ट मॉडल हज़ारों वास्तविक रोगियों के रिकॉर्ड पर प्रशिक्षित है।",
