    "home_faq_q2": "இரத்தப் பரிசோதனை பிடிஎஃப் அறிக்கைகளை நேரடியாகப் பதிவேற்ற முடியுமா?",
    "home_faq_a2": "ஆம்! எங்கள் ஜெமினி விஷன் ஓசிஆர் பிடிஎஃப் கோப்புகளைப் பகுப்பாய்வு செய்து தானாகப் பூர்த்தி செய்கிறது.",
    "home_faq_q3": "நியூட்ரி-ஏஐ சைவ உணவுகளை ஆதரிக்கிறதா?",
    "home_faq_a3": "நிச்சயமாக! எங்கள் உணவுப் பரிந்துரை புரதம், இரும்பு மற்றும் பி12 தேவையை உறுதி செய்கிறது.",
    "home_faq_q4": "ஆப் ஸ்டோர் பதிவிறக்கம் இன்றி PWA எவ்வாறு இயங்குகிறது?",
    "home_faq_a4": "நியூட்ரி-ஏஐ PWA தொழில்நுட்பத்தில் உருவாக்கப்பட்டது. க்ரோமில் சென்று 'நிறுவு' என்பதைத் தட்டவும்.",
    "home_pwa_banner_title": "எந்தச் சாதனத்திலும் நியூட்ரி-ஏஐ செயலியை நிறுவவும்",
    "home_pwa_banner_subtitle": "ஆஃப்லைன் உணவுத் திட்டங்கள் மற்றும் உடனடி உணவு ஸ்கேனிங்கை அனுபவிக்கவும்.",
